// Writes src/spells/srd-spells.ts from the 5e-bits SRD database's spell file
// (https://github.com/5e-bits/5e-database, src/2014/en/5e-SRD-Spells.json, MIT licence; the text is
// the SRD 5.1's, CC-BY-4.0). Run once when the data changes:
//   node scripts/spells-from-srd.mjs path/to/5e-SRD-Spells.json
// then `pnpm format`. The plugin never fetches anything: the generated file ships with it.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const source = process.argv[2];
if (source === undefined) {
	console.error('Usage: node scripts/spells-from-srd.mjs path/to/5e-SRD-Spells.json');
	process.exit(1);
}

/**
 * The database writes ability names in lower case ("dexterity saving throw"), where the SRD does
 * not, and has a few broken dice ("1dl0", "d 100", "10d 10").
 */
function abilities(text) {
	return text
		.replace(/(\d)dl0\b/g, '$1d10')
		.replace(/\b(\d*)d (\d+)\b/g, '$1d$2')
		.replace(
			/\b(strength|dexterity|constitution|intelligence|wisdom|charisma)\b(?= (saving throw|check|modifier|score|\())/g,
			(word) => word.charAt(0).toUpperCase() + word.slice(1),
		);
}

/** Paragraphs as Markdown: table rows on consecutive lines, everything else apart. */
function markdown(paragraphs) {
	let text = '';
	for (const [i, p] of paragraphs.entries()) {
		const table = p.startsWith('|') && (paragraphs[i - 1] ?? '').startsWith('|');
		text += i === 0 ? abilities(p) : (table ? '\n' : '\n\n') + abilities(p);
	}
	return text;
}

/** `Self (15-foot cone)` as the SRD writes it, from the range and the area. */
function range(spell) {
	const area = spell.area_of_effect;
	if (spell.range !== 'Self' || area === undefined) return spell.range;
	return area.type === 'sphere'
		? `Self (${area.size}-foot radius)`
		: `Self (${area.size}-foot ${area.type})`;
}

const spells = JSON.parse(readFileSync(source, 'utf8'))
	.map((s) => ({
		index: s.index,
		name: s.name,
		level: s.level,
		school: s.school.index,
		casting: s.casting_time,
		range: range(s),
		components: s.components,
		material: s.material ?? '',
		duration: s.duration,
		concentration: s.concentration,
		ritual: s.ritual,
		classes: s.classes.map((c) => c.index),
		damage: (s.damage ?? []).flatMap((d) => (d.damage_type ? [d.damage_type.index] : [])),
		save: s.dc?.dc_type.index ?? null,
		attack: s.attack_type ?? null,
		text: markdown(s.desc),
		higher: markdown(s.higher_level ?? []),
	}))
	.sort((a, b) => a.name.localeCompare(b.name));

const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'spells', 'srd-spells.ts');
writeFileSync(
	out,
	`// The 319 spells of the SRD 5.1 (CC-BY-4.0, see NOTICE.md), generated by
// scripts/spells-from-srd.mjs from the 5e-bits SRD database. Do not edit by hand.

import type { SrdSpell } from './model';

export const SRD_SPELLS: readonly SrdSpell[] = ${JSON.stringify(spells, null, 2)};
`,
);
console.log(`Wrote ${spells.length} spells to ${out}`);
